#include <bits/stdc++.h>
using namespace std;

class OrderedStream {
    vector<string> data;
    int ptr;
public:
    OrderedStream(int n) : data(n + 1), ptr(1) {}
    vector<string> insert(int idKey, string value) {
        data[idKey] = value;
        vector<string> result;
        while (ptr < (int)data.size() && !data[ptr].empty())
            result.push_back(data[ptr++]);
        return result;
    }
};
